<?php
declare(strict_types=1);
require_once __DIR__.'/owner-bug-tracker-update-v1.php';

/** Update a bounded set of versioned bugs atomically; replay returns the saved batch receipt. */
function narrrfs_owner_bug_bulk(SQLite3 $db, array $request, string $actor): array {
    $ids=$request['cases']??null; $action=$request['action']??null; $value=$request['value']??null; $key=$request['idempotency_key']??null;
    if (!preg_match('/^\d{17,20}$/D',$actor) || !is_array($ids) || count($ids)<1 || count($ids)>50 || !in_array($action,['status','assign'],true) || !is_string($key) || !preg_match('/^[A-Za-z0-9_-]{24,128}$/D',$key) || ($action==='status' && (!is_int($value)||$value<1)) || ($action==='assign' && $value!==null && (!is_string($value)||trim($value)===''||strlen($value)>100))) throw new NarrrfsOwnerBugTrackerUpdateException(400,'invalid_bulk_request');
    $cases=[]; foreach($ids as $c){if(!is_array($c)||!is_int($c['bug_id']??null)||$c['bug_id']<1||!is_int($c['expected_version']??null)||$c['expected_version']<1||isset($cases[$c['bug_id']]))throw new NarrrfsOwnerBugTrackerUpdateException(400,'invalid_bulk_request');$cases[$c['bug_id']]=$c['expected_version'];} ksort($cases,SORT_NUMERIC);
    $hash=hash('sha256',json_encode([$action,$value,$cases],JSON_THROW_ON_ERROR));$receiptKey=hash('sha256',$actor."\n".'bulk:'.$key);
    $db->enableExceptions(true);$db->busyTimeout(5000);$db->exec('PRAGMA foreign_keys=ON');$db->exec('BEGIN IMMEDIATE');
    try {
        $q=$db->prepare('SELECT request_hash,result_json,expires_at FROM tbl_owner_control_bug_update_receipts WHERE actor_subject=:a AND idempotency_key_hash=:k');$q->bindValue(':a',$actor);$q->bindValue(':k',$receiptKey);$r=$q->execute()->fetchArray(SQLITE3_ASSOC);
        if(is_array($r)){if(!hash_equals($r['request_hash'],$hash))throw new NarrrfsOwnerBugTrackerUpdateException(409,'idempotency_key_reused');if(strtotime($r['expires_at'].' UTC')<=time())throw new NarrrfsOwnerBugTrackerUpdateException(409,'idempotency_key_expired');$saved=json_decode($r['result_json'],true,32,JSON_THROW_ON_ERROR);$db->exec('COMMIT');return ['replayed'=>true,'cases'=>$saved['cases']];}
        $result=[]; foreach($cases as $id=>$version){$q=$db->prepare('SELECT title,description,category_id,priority_id,status_id,assigned_to,resolution_notes,owner_control_version FROM tbl_bug_reports WHERE bug_id=:id');$q->bindValue(':id',$id,SQLITE3_INTEGER);$row=$q->execute()->fetchArray(SQLITE3_ASSOC);if(!$row||(int)$row['owner_control_version']!==$version)throw new NarrrfsOwnerBugTrackerUpdateException(409,'bulk_version_conflict');$in=['title'=>$row['title'],'description'=>$row['description'],'category_id'=>(int)$row['category_id'],'priority_id'=>(int)$row['priority_id'],'status_id'=>$action==='status'?$value:(int)$row['status_id'],'assigned_to'=>$action==='assign'?$value:$row['assigned_to'],'resolution_notes'=>$row['resolution_notes'],'change_reason'=>'Owner Control bulk '.$action,'expected_version'=>$version,'idempotency_key'=>hash('sha256','bulk-case:'.$key.':'.$id)];$one=narrrfs_owner_bug_tracker_update($db,$id,$in,$actor,true);$result[]=['bug_id'=>$id,'version'=>(int)$one['bug']['owner_control_version']];}
        $first=(int)array_key_first($cases);$q=$db->prepare("INSERT INTO tbl_owner_control_bug_update_receipts(actor_subject,idempotency_key_hash,request_hash,bug_id,expected_version,result_version,result_json,expires_at) VALUES(:a,:k,:h,:b,:v,:r,:j,datetime(CURRENT_TIMESTAMP,'+24 hours'))");foreach([':a'=>$actor,':k'=>$receiptKey,':h'=>$hash,':b'=>$first,':v'=>$cases[$first],':r'=>$result[0]['version'],':j'=>json_encode(['cases'=>$result],JSON_THROW_ON_ERROR)] as $k=>$v)$q->bindValue($k,$v,is_int($v)?SQLITE3_INTEGER:SQLITE3_TEXT);$q->execute();$db->exec('COMMIT');return ['replayed'=>false,'cases'=>$result];
    } catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
